// LANL2DZ exponents such as 0.318 are basis data, not approximations of 1/pi.
#![allow(clippy::approx_constant)]
//! ferric-owned ECP quadrature ([`ferric_integrals::ecp_quad`], the
//! `EcpBackend::Quadrature` backend) — FINDINGS "Iteration 25".
//!
//! Oracles (pinned, never called at test time): PySCF 2.13 `ECPscalar_sph`
//! with the 1e-3 zero-weight screen guard, an independent radial × Lebedev
//! quadrature, mpmath Bessel values, and the Python prototype's own values —
//! all in `testdata/reference/ecp_quadrature_refs.json`, generated by
//! `OPENBLAS_NUM_THREADS=1 /home/matt/qc/ferric/.venv/bin/python scripts/gen_ecp_quadrature_refs.py`.
//! Fixtures: HI/LANL2DZ (100 triples: 5 × 5 shells, 4 ECP centres incl. one
//! ON the bra I shells) and AuH/def2-SVP + def2-ECP (675 triples, f shells, 3
//! centres incl. on-Au).
//!
//! Bars come from the prototype's measurements (FINDINGS tables) with
//! headroom; every accuracy test has a negative control that must FAIL it
//! (libecpint, or a deliberately broken construction via `QuadKnobs`).

use ferric_core::basis;
use ferric_core::mol::Molecule;
use ferric_integrals::ecp::{
    ecp_block_deriv_spherical_with_backend, ecp_block_spherical_quadrature_knobs,
    ecp_block_spherical_with_backend, ecp_deriv_atom_ids, ecp_matrix_deriv_spherical_with_backend,
    ecp_matrix_spherical_with_backend, gto_norm, EcpBackend, EcpCenter, EcpGaussianShell,
};
use ferric_integrals::ecp_quad::bessel::ktil;
use ferric_integrals::ecp_quad::{semi_local_cart, Mutation, QuadKnobs, RadialRule};
use serde::Deserialize;
use std::sync::OnceLock;

const Q: EcpBackend = EcpBackend::Quadrature;
const LIB: EcpBackend = EcpBackend::Libecpint;

// ------------------------------------------------------------ pinned references

#[derive(Deserialize, Clone)]
struct ShellJ {
    l: i32,
    center: [f64; 3],
    exps: Vec<f64>,
    coefs: Vec<f64>,
}

#[derive(Deserialize, Clone)]
struct EcpJ {
    center: [f64; 3],
    ams: Vec<i32>,
    ns: Vec<i32>,
    exps: Vec<f64>,
    coefs: Vec<f64>,
}

#[derive(Deserialize)]
struct Fixture {
    bra: Vec<ShellJ>,
    ket: Vec<ShellJ>,
    ecps: Vec<EcpJ>,
    pyscf: Vec<Vec<f64>>,
    proto: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct Tiny {
    bra: ShellJ,
    ket: ShellJ,
    ecp: EcpJ,
    lebedev: Vec<f64>,
    pyscf: Vec<f64>,
}

#[derive(Deserialize)]
struct Bessel {
    z: Vec<f64>,
    nmax: usize,
    values: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct Refs {
    hi: Fixture,
    auh: Fixture,
    tiny: Tiny,
    bessel: Bessel,
}

fn refs() -> &'static Refs {
    static R: OnceLock<Refs> = OnceLock::new();
    R.get_or_init(|| {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../testdata/reference/ecp_quadrature_refs.json"
        );
        let text = std::fs::read_to_string(path).unwrap_or_else(|e| {
            panic!("read {path}: {e}\nrun scripts/gen_ecp_quadrature_refs.py first")
        });
        serde_json::from_str(&text).expect("parse ecp_quadrature_refs.json")
    })
}

fn shell(s: &ShellJ) -> EcpGaussianShell {
    EcpGaussianShell {
        l: s.l,
        center: s.center,
        exponents: s.exps.clone(),
        coefficients: s.coefs.clone(),
    }
}

fn ecp(e: &EcpJ) -> EcpCenter {
    EcpCenter {
        center: e.center,
        ams: e.ams.clone(),
        ns: e.ns.clone(),
        exponents: e.exps.clone(),
        coefficients: e.coefs.clone(),
    }
}

/// A fixture as (bra, ket, ecps) plus its triples `(a, b, u, index)` in the
/// pinned order (u fastest).
struct Fx {
    bra: Vec<EcpGaussianShell>,
    ket: Vec<EcpGaussianShell>,
    ecps: Vec<EcpCenter>,
}

impl Fx {
    fn from(f: &Fixture) -> Self {
        Self {
            bra: f.bra.iter().map(shell).collect(),
            ket: f.ket.iter().map(shell).collect(),
            ecps: f.ecps.iter().map(ecp).collect(),
        }
    }
    fn triples(&self) -> Vec<(usize, usize, usize, usize)> {
        let (nk, ne) = (self.ket.len(), self.ecps.len());
        (0..self.bra.len() * nk * ne)
            .map(|t| (t / (nk * ne), (t / ne) % nk, t % ne, t))
            .collect()
    }
}

fn hi() -> Fx {
    Fx::from(&refs().hi)
}

fn auh() -> Fx {
    Fx::from(&refs().auh)
}

/// Spherical block of ONE triple.
fn val(b: EcpBackend, sa: &EcpGaussianShell, sb: &EcpGaussianShell, e: &EcpCenter) -> Vec<f64> {
    ecp_block_spherical_with_backend(
        b,
        std::slice::from_ref(sa),
        std::slice::from_ref(sb),
        std::slice::from_ref(e),
        None,
    )
    .unwrap()
}

fn val_knobs(
    sa: &EcpGaussianShell,
    sb: &EcpGaussianShell,
    e: &EcpCenter,
    k: &QuadKnobs,
) -> Vec<f64> {
    ecp_block_spherical_quadrature_knobs(
        std::slice::from_ref(sa),
        std::slice::from_ref(sb),
        std::slice::from_ref(e),
        None,
        k,
    )
    .unwrap()
}

fn maxdiff(a: &[f64], b: &[f64]) -> f64 {
    assert_eq!(a.len(), b.len());
    a.iter()
        .zip(b)
        .fold(0.0_f64, |m, (x, y)| m.max((x - y).abs()))
}

fn amax(v: &[f64]) -> f64 {
    v.iter().fold(0.0_f64, |m, x| m.max(x.abs()))
}

fn dist(a: [f64; 3], b: [f64; 3]) -> f64 {
    (0..3).map(|k| (a[k] - b[k]).powi(2)).sum::<f64>().sqrt()
}

fn moved_shell(s: &EcpGaussianShell, x: usize, d: f64) -> EcpGaussianShell {
    let mut t = s.clone();
    t.center[x] += d;
    t
}

fn moved_ecp(e: &EcpCenter, x: usize, d: f64) -> EcpCenter {
    let mut t = e.clone();
    t.center[x] += d;
    t
}

/// Copy of `e` keeping only the listed channels (others' coefficients zeroed;
/// the local channel keeps its max-am tag).
fn only_channels(e: &EcpCenter, keep: &[i32]) -> EcpCenter {
    let mut t = e.clone();
    for (k, c) in t.coefficients.iter_mut().enumerate() {
        if !keep.contains(&e.ams[k]) {
            *c = 0.0;
        }
    }
    t
}

/// Richardson-extrapolated central FD `(4 FD(h/2) − FD(h))/3`.
fn richardson(f: &dyn Fn(f64) -> Vec<f64>, h: f64) -> Vec<f64> {
    let fd = |hh: f64| -> Vec<f64> {
        let (p, m) = (f(hh), f(-hh));
        p.iter()
            .zip(&m)
            .map(|(a, b)| (a - b) / (2.0 * hh))
            .collect()
    };
    let (f1, f2) = (fd(h), fd(0.5 * h));
    f1.iter()
        .zip(&f2)
        .map(|(a, b)| (4.0 * b - a) / 3.0)
        .collect()
}

// ============================================================ building blocks

/// k̃_n(z) = e^{−z} i_n(z) vs 40-digit mpmath, n ≤ 16, every regime edge
/// (0, 1e-8, the 4n switch points) and z ∈ [1e-300, 1e5]; each n_max the
/// kernel is called with. Bar 1e-14 relative (prototype measured ≤ 2.3e-15 for
/// n ≤ 12); an absolute 1e-300 floor covers subnormal results.
#[test]
fn bessel_matches_pinned_mpmath_table() {
    let b = &refs().bessel;
    assert_eq!(b.nmax, 16);
    let mut out = [0.0; 17];
    let mut worst = 0.0_f64;
    let mut at = (0usize, 0usize, 0.0f64);
    let mut checked = 0usize;
    for nm in [0usize, 1, 3, 6, 9, 12, 16] {
        for (iz, &z) in b.z.iter().enumerate() {
            ktil(nm, z, &mut out);
            for n in 0..=nm {
                let r = b.values[iz][n];
                let d = (out[n] - r).abs();
                checked += 1;
                if d <= 1e-300 {
                    continue;
                }
                let rel = if r != 0.0 { d / r.abs() } else { f64::INFINITY };
                if rel > worst {
                    worst = rel;
                    at = (nm, n, z);
                }
            }
        }
    }
    eprintln!(
        "ktil vs mpmath: {checked} values, worst relative {worst:.2e} (n_max {}, n {}, z {:e})",
        at.0, at.1, at.2
    );
    assert!(checked > 5000, "vacuous table");
    assert!(worst < 1e-14, "{worst:e} at {at:?}");
}

/// Production (radial tensor R + one angular contraction) vs forming
/// F^A_lm(r), F^B_lm(r) at every node and contracting Σ_m F^A F^B — an
/// independent contraction of the same projections (prototype ≤ 1.9e-13).
#[test]
fn radial_tensor_form_equals_explicit_projections() {
    let f = auh();
    let sel = [0usize, 6, 9, 11, 14];
    let mut worst = 0.0_f64;
    let mut n = 0;
    for (k, (a, b, u)) in sel
        .iter()
        .flat_map(|&a| {
            sel.iter()
                .flat_map(move |&b| (0..3).map(move |u| (a, b, u)))
        })
        .enumerate()
    {
        if k % 2 == 1 {
            continue;
        }
        let v1 = semi_local_cart(&f.bra[a], &f.ket[b], &f.ecps[u], false).unwrap();
        let v2 = semi_local_cart(&f.bra[a], &f.ket[b], &f.ecps[u], true).unwrap();
        worst = worst.max(maxdiff(&v1, &v2) / amax(&v2).max(1e-3));
        n += 1;
    }
    eprintln!("radial-tensor vs explicit F contraction: {n} triples, worst {worst:.2e}");
    assert!(worst < 1e-12, "{worst:e}");
}

/// Screening skips (primitive pair, term) windows whose bound is < 1e-16:
/// on the AuH f-shell fixture it changes no element by more than 1e-20
/// (prototype 8.6e-24).
#[test]
fn screening_changes_nothing_measurable() {
    let f = auh();
    let off = QuadKnobs {
        screen: false,
        ..QuadKnobs::default()
    };
    let sel = [0usize, 9, 11, 14];
    let mut worst = 0.0_f64;
    for &a in &sel {
        for &b in &sel {
            for e in &f.ecps {
                let on = val(Q, &f.bra[a], &f.ket[b], e);
                let of = val_knobs(&f.bra[a], &f.ket[b], e, &off);
                worst = worst.max(maxdiff(&on, &of));
            }
        }
    }
    eprintln!("screen on vs off: max |Δ| {worst:.2e}");
    assert!(worst < 1e-20, "{worst:e}");
}

// ============================================================ values vs oracles

/// `(max |ours − pyscf|, max over |pyscf| > 1e-6, max |ours − prototype|)`.
fn fixture_vs_refs(f: &Fx, r: &Fixture) -> (f64, f64, f64, usize) {
    let (mut all, mut big, mut proto, mut n) = (0.0_f64, 0.0_f64, 0.0_f64, 0usize);
    for (a, b, u, t) in f.triples() {
        let v = val(Q, &f.bra[a], &f.ket[b], &f.ecps[u]);
        for ((x, p), q) in v.iter().zip(&r.pyscf[t]).zip(&r.proto[t]) {
            let d = (x - p).abs();
            all = all.max(d);
            if p.abs() > 1e-6 {
                big = big.max(d);
            }
            proto = proto.max((x - q).abs());
            n += 1;
        }
    }
    (all, big, proto, n)
}

